	private DirectoryState analyzeDirectory(Path walDirectory) throws IOException {
		if (!Files.isDirectory(walDirectory)) {
			return new DirectoryState(false, 0);
		}
		int maxSequence = 0;
		boolean hasSegments = false;
		try (var stream = Files.list(walDirectory)) {
			var paths = stream.iterator();
			while (paths.hasNext()) {
				Path path = paths.next();
				Matcher matcher = SEGMENT_PATTERN.matcher(path.getFileName().toString());
				if (matcher.matches()) {
					hasSegments = true;
					try {
						int segment = readSegmentSequence(path);
						if (segment > maxSequence) {
							maxSequence = segment;
						}
					} catch (IOException e) {
						logger.warn("Failed to read WAL segment header for {}", path.getFileName(), e);
					}
				}
			}
		}
		return new DirectoryState(hasSegments, maxSequence);
	}

	static int readSegmentSequence(Path path) throws IOException {
		boolean compressed = path.getFileName().toString().endsWith(".gz");
		try (var rawIn = new BufferedInputStream(Files.newInputStream(path));
				InputStream in = compressed ? new GZIPInputStream(rawIn) : rawIn) {
			byte[] lenBytes = in.readNBytes(4);
			if (lenBytes.length < 4) {
				return 0;
			}
			ByteBuffer lenBuf = ByteBuffer.wrap(lenBytes).order(ByteOrder.LITTLE_ENDIAN);
			int frameLen = lenBuf.getInt();
			if (frameLen <= 0 || frameLen > MAX_FRAME_BYTES) {
				return 0;
			}
			LimitedInputStream frame = new LimitedInputStream(in, frameLen);
			int sequence = 0;
			JsonFactory factory = ValueStoreWalMemory.newJsonFactory();
			try (JsonParser parser = factory.createParser(ObjectReadContext.empty(), frame)) {
				if (parser.nextToken() != JsonToken.START_OBJECT) {
					return 0;
				}
				JsonToken token;
				while ((token = parser.nextToken()) != JsonToken.END_OBJECT) {
					if (token == null) {
						return 0;
					}
					String field = parser.currentName();
					parser.nextToken();
					if ("segment".equals(field)) {
						sequence = parser.getIntValue();
					} else {
						parser.skipChildren();
					}
				}
			}
			try {
				in.skipNBytes(frame.remaining);
			} catch (EOFException e) {
				return 0;
			}
			return in.readNBytes(4).length == 4 ? sequence : 0;
		}
	}

	private static final class LimitedInputStream extends FilterInputStream {
		private long remaining;

		LimitedInputStream(InputStream input, long remaining) {
			super(input);
			this.remaining = remaining;
		}

		@Override
		public int read() throws IOException {
			if (remaining == 0) {
				return -1;
			}
			int value = in.read();
			if (value >= 0) {
				remaining--;
			}
			return value;
		}

		@Override
		public int read(byte[] bytes, int offset, int length) throws IOException {
			if (length == 0) {
				return 0;
			}
			if (remaining == 0) {
				return -1;
			}
			int read = in.read(bytes, offset, (int) Math.min(length, remaining));
			if (read > 0) {
				remaining -= read;
			}
			return read;
		}

		@Override
		public void close() {
			// The segment owner closes the stream after reading the frame checksum.
		}
	}

